mockups.css:
.app{--primary:#1b8168;--on-primary:#fff;--primary-fg:#117b63;--primary-soft:#dcf5ec;--accent-soft:#eaf2ce;--accent-fg:#56701f;
--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;
font-family:Figtree,"Segoe UI",system-ui,sans-serif;color:var(--ink);background:var(--stage);min-height:100%;padding:16px 0}
.phone{max-width:420px;margin:0 auto;background:var(--cream);padding:18px 16px 28px;border-radius:24px}
.top{display:flex;justify-content:space-between;font-size:14px;margin-bottom:14px}
.top a{font-weight:800;color:var(--primary-fg);text-decoration:none}
h1{font-family:"Bricolage Grotesque","Segoe UI",system-ui,sans-serif;font-size:26px;line-height:1.15;font-weight:800;margin:0}
.sum{margin-top:6px;font-size:13px;color:var(--ink-soft)}
.toggle{display:flex;justify-content:space-between;align-items:center;margin:12px 0;padding:10px 12px;border:1px solid var(--line);background:var(--paper);border-radius:16px;font-size:14px;font-weight:700}
.sw{width:42px;height:24px;border-radius:12px;background:var(--primary);position:relative}.sw:after{content:"";position:absolute;right:3px;top:3px;width:18px;height:18px;border-radius:50%;background:#fff}
h2{font-size:16px;font-weight:700;margin:4px 0 10px;display:flex;gap:8px;align-items:center}
.grid{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:1fr 1fr;gap:12px}
.card{position:relative;display:flex;flex-direction:column;border:1px solid var(--line);background:var(--paper);border-radius:16px;padding:10px;cursor:pointer}
.card.dashed{border-style:dashed;border-color:var(--line-strong)}
.thumb{aspect-ratio:1/1;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:34px}
.dim{opacity:.6}
.name{margin-top:8px;font-size:13px;font-weight:700}
.cond{font-size:11px;color:var(--ink-soft);margin:2px 0 8px}
.pills{margin-top:auto;display:flex;gap:4px;flex-wrap:wrap}
.pill{font-size:11px;font-weight:800;border-radius:999px;padding:2px 8px;background:var(--primary-soft);color:var(--primary-fg)}
.pill.res{background:var(--line);color:var(--ink-soft)}
.new{position:absolute;top:16px;left:16px;border-radius:999px;background:var(--primary);color:var(--on-primary);font-size:11px;font-weight:800;padding:2px 8px}
.foot{margin-top:6px;font-size:12px;color:var(--ink-soft)}.foot b{color:var(--ink)}
.sec{margin-top:22px;border-top:1px solid var(--line);padding-top:16px}
.lead{margin:-4px 0 12px;font-size:13px;color:var(--ink-soft)}
.empty{display:flex;flex-direction:column;align-items:center;gap:10px;border:1.5px dashed var(--line-strong);border-radius:28px;background:var(--paper);padding:28px 20px;text-align:center}
.empty .ic{width:64px;height:64px;border-radius:24px;background:var(--accent-soft);color:var(--accent-fg);display:flex;align-items:center;justify-content:center;font-size:28px}
.empty h3{font-family:"Bricolage Grotesque",system-ui,sans-serif;font-size:20px;font-weight:800;margin:0}
.empty p{font-size:15px;color:var(--ink-soft);margin:0}
.status{display:flex;gap:10px;align-items:center;border-radius:16px;background:var(--primary-soft);color:var(--primary-fg);font-size:14px;font-weight:700;padding:10px 12px;margin-bottom:12px}
.dot{width:10px;height:10px;border-radius:50%;background:var(--primary)}
.skel{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:1fr 1fr;gap:12px}
.skel li{border:1px solid var(--line);background:var(--paper);border-radius:16px;padding:10px}
.skel span{display:block;background:var(--line);border-radius:999px}
.valid{margin:14px 0 10px;font-size:13px;color:var(--ink-soft)}
.btn{display:flex;min-height:48px;align-items:center;justify-content:center;border-radius:999px;padding:0 20px;font-size:15px;font-weight:800}
.btn.p{background:var(--primary);color:var(--on-primary)}.btn.g{border:1.5px solid var(--line);background:var(--paper);flex:1}.btn.d{border:1.5px solid #f6e4e2;background:var(--paper);color:#b23b3b;flex:1}
.row{display:flex;gap:10px;margin-top:10px}

